svg.script:


const parentDoc = window.parent.document;

	function checkForTitleMatch() {
		let value = parentDoc.getElementById('letter').value;
		if (value === "") {
			document.querySelectorAll("ellipse").forEach(
				(ellipse) => ellipse.setAttribute('stroke', 'black')
			)
		}
		try {
			const matchingTitle = Array.from(document.querySelectorAll("text")).find(
				(title) => title.textContent.trim() === value
			);

			if (matchingTitle) {
				// console.log("✅ Matching SVG <title> found:", matchingTitle);

				const ellipse = matchingTitle.previousElementSibling;
				ellipse.setAttribute('stroke', '#007acc');;

			} else {
				console.log("🔍 No matching SVG <title> :" + value
					+ "found yet.");
			}
		} catch (err) {
			console.error("⚠️ Error accessing parent document:", err);
		}
	}

	// Check every 500ms
	const checkInterval = setInterval(checkForTitleMatch, 100);
